Item.method_code:
/*
    帳票マスタと開達書式共通
        基本として、非編集中、非ロックの必要がありさらに以下の条件
    
        表示：そのアイテムの管理者かCreaterで、ステートが公開中の時のみ表示
        非表示：↑以外
*/
const Release = "Release";

// Innovatorオブジェクト生成
var iomInv = aras.IomInnovator;

// 親Item情報取得
var parentItem = iomInv.newItem(itemTypeName,"get");
parentItem.setID(itemID);
parentItem.setAttribute("select", "managed_by_id,state");
parentItem = parentItem.apply();

// アイテムが取得出来ない場合(新規作成時)は非表示
if(parentItem.getItemCount()<1) return {hidden:true};

// ログインユーザーがpromote可能かチェックする
const superUserID = "6B14D33C4A7D41C188CCF2BC15BD01A3"; // Super User
const arasPlmID = "56A96DA9E981481688563E2D14D5D878"; // Aras PLM
const adminID = "2618D6F5A90949BAA7E920D1B04C7EE1"; // administrators

var userID = aras.getUserID();
var ownedByID = parentItem.getProperty('managed_by_id');
var createdByID = parentItem.getProperty('created_by_id');
var identityList = aras.getIdentityList();

var canRevise = false;
if(userID==createdByID || identityList.indexOf(ownedByID)>-1 || identityList.indexOf(superUserID)>-1 ||
 identityList.indexOf(arasPlmID)>-1 || identityList.indexOf(adminID)>-1)
{
  canRevise = true;  
}

//公開中か
var getState = parentItem.getProperty("state","");
var flag = (getState === Release);

var isView = !window.isEditMode && parentItem.getLockStatus()==0 && canRevise && flag;

return {
    hidden:  !isView,
    disabled: false
};
